/**
 * Config plugin: Gradle settings that make native rebuilds faster.
 *
 *  - org.gradle.caching: reuse compiled outputs when the inputs have not changed. This is what makes
 *    `expo prebuild --clean` / a fresh CI or EAS machine fast IF the cache directory is restored
 *    (eas.json `cache.customPaths` and the setup-gradle action both restore ~/.gradle/caches).
 *    Without it only downloaded dependencies are cached, never compiled code.
 *  - org.gradle.jvmargs: the Expo template default (2 GB) makes a React Native build spend a lot of time in GC.
 *
 * `android/` is generated by `expo prebuild`, so this is the only place these can live.
 */
const { withGradleProperties } = require('expo/config-plugins');

const PROPS = {
  'org.gradle.caching': 'true',
  'org.gradle.jvmargs': '-Xmx3g -XX:MaxMetaspaceSize=768m',
};

module.exports = function withGradleSpeed(config) {
  return withGradleProperties(config, (cfg) => {
    for (const [key, value] of Object.entries(PROPS)) {
      const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === key);
      if (existing) existing.value = value;
      else cfg.modResults.push({ type: 'property', key, value });
    }
    return cfg;
  });
};
